CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.contact_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,phone text,budget text,message text NOT NULL,source text,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_submissions TO anon,authenticated; GRANT SELECT,DELETE ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_contact ON public.contact_submissions FOR INSERT TO anon,authenticated WITH CHECK(length(name) BETWEEN 1 AND 100 AND length(email)<=255 AND length(message)<=3000);
CREATE POLICY admin_contact ON public.contact_submissions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY delete_contact ON public.contact_submissions FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.job_openings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,team text NOT NULL,location text NOT NULL DEFAULT 'Ahmedabad, India',employment_type text NOT NULL DEFAULT 'Full-time',description text,is_open boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.job_openings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_openings TO authenticated; GRANT ALL ON public.job_openings TO service_role;
ALTER TABLE public.job_openings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_jobs ON public.job_openings FOR SELECT TO anon,authenticated USING(is_open); CREATE POLICY admin_jobs ON public.job_openings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.blog_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,category text NOT NULL,summary text NOT NULL,body text,read_time text,is_featured boolean NOT NULL DEFAULT false,is_published boolean NOT NULL DEFAULT true,published_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.blog_posts TO authenticated; GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_posts ON public.blog_posts FOR SELECT TO anon,authenticated USING(is_published); CREATE POLICY admin_posts ON public.blog_posts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.job_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),role_title text NOT NULL,job_opening_id uuid REFERENCES public.job_openings(id) ON DELETE SET NULL,full_name text NOT NULL,email text NOT NULL,phone text,message text,resume_path text,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.job_applications TO anon,authenticated; GRANT SELECT,DELETE ON public.job_applications TO authenticated; GRANT ALL ON public.job_applications TO service_role;
ALTER TABLE public.job_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_application ON public.job_applications FOR INSERT TO anon,authenticated WITH CHECK(length(full_name) BETWEEN 1 AND 100 AND length(email)<=255);
CREATE POLICY admin_applications ON public.job_applications FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin')); CREATE POLICY delete_applications ON public.job_applications FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.testimonials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,role text,company text,quote text NOT NULL,is_published boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.testimonials TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.testimonials TO authenticated; GRANT ALL ON public.testimonials TO service_role;
ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_testimonials ON public.testimonials FOR SELECT TO anon,authenticated USING(is_published); CREATE POLICY admin_testimonials ON public.testimonials FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.work_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,client text NOT NULL,category text NOT NULL DEFAULT 'Digital',summary text NOT NULL,result text,image_url text,is_published boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.work_projects TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.work_projects TO authenticated; GRANT ALL ON public.work_projects TO service_role;
ALTER TABLE public.work_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_work ON public.work_projects FOR SELECT TO anon,authenticated USING(is_published); CREATE POLICY admin_work ON public.work_projects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.client_logos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,logo_url text,is_published boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.client_logos TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_logos TO authenticated; GRANT ALL ON public.client_logos TO service_role;
ALTER TABLE public.client_logos ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_logos ON public.client_logos FOR SELECT TO anon,authenticated USING(is_published); CREATE POLICY admin_logos ON public.client_logos FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.partner_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company text NOT NULL,contact_name text NOT NULL,email text NOT NULL,phone text,website text,partnership_type text,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.partner_applications TO anon,authenticated; GRANT SELECT,DELETE ON public.partner_applications TO authenticated; GRANT ALL ON public.partner_applications TO service_role;
ALTER TABLE public.partner_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_partner ON public.partner_applications FOR INSERT TO anon,authenticated WITH CHECK(length(company) BETWEEN 1 AND 200 AND length(email)<=255 AND length(message)<=3000); CREATE POLICY admin_partner ON public.partner_applications FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin')); CREATE POLICY delete_partner ON public.partner_applications FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.popup_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,title text NOT NULL,description text NOT NULL,cta_text text NOT NULL DEFAULT 'Let’s talk',image_url text,kind text NOT NULL DEFAULT 'lead' CHECK(kind IN ('lead','announcement')),trigger_type text NOT NULL DEFAULT 'delay' CHECK(trigger_type IN ('delay','scroll','exit')),delay_seconds integer NOT NULL DEFAULT 25 CHECK(delay_seconds BETWEEN 5 AND 300),scroll_percent integer NOT NULL DEFAULT 50 CHECK(scroll_percent BETWEEN 10 AND 95),cooldown_days integer NOT NULL DEFAULT 7 CHECK(cooldown_days BETWEEN 1 AND 90),target_path text NOT NULL DEFAULT '*',cta_path text NOT NULL DEFAULT '/contact' CHECK(cta_path IN ('/contact','/services','/work','/about','/partner','/career','/blog')),is_active boolean NOT NULL DEFAULT false,starts_at timestamptz,ends_at timestamptz,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.popup_campaigns TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.popup_campaigns TO authenticated; GRANT ALL ON public.popup_campaigns TO service_role;
ALTER TABLE public.popup_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_campaigns ON public.popup_campaigns FOR SELECT TO anon,authenticated USING(is_active AND (starts_at IS NULL OR starts_at<=now()) AND (ends_at IS NULL OR ends_at>now())); CREATE POLICY admin_campaigns ON public.popup_campaigns FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER blog_touch BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER jobs_touch BEFORE UPDATE ON public.job_openings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER campaigns_touch BEFORE UPDATE ON public.popup_campaigns FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
